-- Consorci Erasmus: estructura SQLite y datos de demostracion.
-- Generado desde migraciones y seeders; compatible con SQLite 3.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "activity_log" ("id" integer primary key autoincrement not null, "log_name" varchar, "description" text not null, "subject_type" varchar, "subject_id" integer, "causer_type" varchar, "causer_id" integer, "properties" text, "created_at" datetime, "updated_at" datetime, "event" varchar, "batch_uuid" varchar);
CREATE TABLE IF NOT EXISTS "educational_centers" ("id" integer primary key autoincrement not null, "code" varchar not null, "name" varchar not null, "city" varchar not null, "province" varchar not null default 'Valencia', "coordinator_name" varchar not null, "coordinator_email" varchar not null, "coordinator_phone" varchar, "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "educational_center_id" integer, "role" varchar not null default 'center_coordinator', "phone" varchar, foreign key("educational_center_id") references "educational_centers"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "erasmus_projects" ("id" integer primary key autoincrement not null, "project_code" varchar not null, "title" varchar not null, "call_year" varchar not null, "academic_year" varchar not null, "start_date" date not null, "end_date" date not null, "total_grant_awarded" numeric not null default '0', "individual_support_grant" numeric not null default '0', "travel_grant" numeric not null default '0', "organizational_support_grant" numeric not null default '0', "inclusion_support_grant" numeric not null default '0', "status" varchar not null default 'active', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "mobility_calls" ("id" integer primary key autoincrement not null, "erasmus_project_id" integer not null, "title" varchar not null, "mobility_type" varchar not null, "academic_year" varchar not null, "application_start_date" date not null, "application_end_date" date not null, "provisional_list_date" date, "final_list_date" date, "total_vacancies" integer not null default '10', "status" varchar not null default 'open', "requirements" text, "created_at" datetime, "updated_at" datetime, "scoring_rubric" text, "program_type" varchar not null default 'GM_STEPV', foreign key("erasmus_project_id") references "erasmus_projects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "host_partners" ("id" integer primary key autoincrement not null, "name" varchar not null, "vat_number" varchar, "country_code" varchar not null, "country_group" integer not null default '2', "city" varchar not null, "address" varchar, "contact_person" varchar, "contact_email" varchar, "contact_phone" varchar, "website" varchar, "sector" varchar, "working_languages" text, "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime, "company_size" varchar, "offers_allowance" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "mobility_payments" ("id" integer primary key autoincrement not null, "mobility_id" integer not null, "payment_type" varchar not null default 'first_payment_80', "amount" numeric not null, "scheduled_date" date not null, "paid_date" date, "status" varchar not null default 'pending', "reference_number" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("mobility_id") references "mobilities"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "application_documents" ("id" integer primary key autoincrement not null, "application_id" integer not null, "document_type" varchar not null, "status" varchar not null default 'pending', "file_path" varchar, "validated_at" datetime, "validated_by" integer, "observations" text, "created_at" datetime, "updated_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("validated_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "application_interviews" ("id" integer primary key autoincrement not null, "application_id" integer not null, "interviewed_at" date, "evaluator_id" integer, "status" varchar not null default 'pending', "certified_languages" text, "selection_reason" text, "preferred_countries" text, "observations" text, "relevant_information" text, "criteria" text, "created_at" datetime, "updated_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("evaluator_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "mobility_bonds" ("id" integer primary key autoincrement not null, "mobility_id" integer not null, "amount" numeric not null, "concept" varchar not null, "destination_iban" varchar not null, "status" varchar not null default 'pending', "validated_at" datetime, "validated_by" integer, "observations" text, "created_at" datetime, "updated_at" datetime, foreign key("mobility_id") references "mobilities"("id") on delete cascade, foreign key("validated_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "disciplinary_incidents" ("id" integer primary key autoincrement not null, "application_id" integer not null, "severity" varchar not null, "description" text not null, "occurred_at" date not null, "instructor_id" integer, "sanction" text, "status" varchar not null default 'open', "excludes_from_resolution" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("instructor_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tutoring_sessions" ("id" integer primary key autoincrement not null, "mobility_id" integer not null, "tutor_scope" varchar not null, "mode" varchar not null, "held_at" datetime not null, "content" text not null, "tutor_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("mobility_id") references "mobilities"("id") on delete cascade, foreign key("tutor_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "mobility_withdrawals" ("id" integer primary key autoincrement not null, "mobility_id" integer not null, "occurred_at" date not null, "after_expenses" tinyint(1) not null default '0', "force_majeure" tinyint(1) not null default '0', "reimbursable_expenses" numeric not null default '0', "funds_to_return" numeric not null default '0', "notes" text, "processed_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("mobility_id") references "mobilities"("id") on delete cascade, foreign key("processed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "domain_notifications" ("id" integer primary key autoincrement not null, "mobility_id" integer not null, "type" varchar not null, "scheduled_for" date not null, "message" text not null, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("mobility_id") references "mobilities"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "applications" ("id" integer primary key autoincrement not null, "mobility_call_id" integer not null, "educational_center_id" integer not null, "first_name" varchar not null, "last_name" varchar not null, "id_document_type" varchar not null default ('DNI'), "id_document_number" varchar not null, "email" varchar not null, "phone" varchar not null, "birth_date" date, "vocational_program" varchar not null, "level" varchar not null default ('grado_medio'), "language_certificate_level" varchar not null default ('B1'), "academic_score" numeric not null default ('0'), "language_score" numeric not null default ('0'), "faculty_report_score" numeric not null default ('0'), "interview_score" numeric not null default ('0'), "inclusion_factor_score" numeric not null default ('0'), "total_score" numeric not null default ('0'), "status" varchar not null default ('submitted'), "cv_path" varchar, "motivation_letter" text, "notes" text, "created_at" datetime, "updated_at" datetime, "birth_place" varchar, "nationality" varchar, "address" varchar, "locality" varchar, "province" varchar, "country_preferences" text, "communications_consent" tinyint(1) not null default ('0'), "absence_count" integer not null default ('0'), "relevant_language_grade" numeric, "score_breakdown" text, "tie_break_reason" varchar, "participant_role" varchar not null default ('student'), "is_minor" tinyint(1) not null default ('0'), "training_branch" varchar, "iban" varchar, "bank_account_holder" varchar, "fewer_opportunities_reason" text, "user_id" integer, foreign key("educational_center_id") references educational_centers("id") on delete cascade on update no action, foreign key("mobility_call_id") references mobility_calls("id") on delete cascade on update no action, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "mobilities" ("id" integer primary key autoincrement not null, "erasmus_project_id" integer not null, "mobility_call_id" integer not null, "application_id" integer, "host_partner_id" integer, "educational_center_id" integer not null, "participant_name" varchar not null, "participant_email" varchar not null, "participant_type" varchar not null default ('student'), "destination_country" varchar not null, "destination_city" varchar not null, "start_date" date not null, "end_date" date not null, "duration_days" integer not null, "travel_type" varchar not null default ('standard'), "fewer_opportunities" tinyint(1) not null default ('0'), "daily_grant_rate" numeric not null default ('0'), "individual_support_amount" numeric not null default ('0'), "travel_amount" numeric not null default ('0'), "inclusion_amount" numeric not null default ('0'), "total_grant_amount" numeric not null default ('0'), "status" varchar not null default ('planned'), "learning_agreement_signed" tinyint(1) not null default ('0'), "grant_agreement_signed" tinyint(1) not null default ('0'), "certificate_of_attendance" tinyint(1) not null default ('0'), "eu_survey_completed" tinyint(1) not null default ('0'), "tutor_in_host" varchar, "tutor_in_origin" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, "participant_role" varchar not null default ('student'), "is_minor" tinyint(1) not null default ('0'), "training_branch" varchar, "iban" varchar, "bank_account_holder" varchar, "fewer_opportunities_reason" text, "user_id" integer, "mobility_kind" varchar, "actual_start_date" date, "actual_end_date" date, "pre_financing_paid" tinyint(1) not null default '0', "pre_financing_paid_at" date, "grant_agreement_signed_at" date, foreign key("educational_center_id") references educational_centers("id") on delete cascade on update no action, foreign key("host_partner_id") references host_partners("id") on delete set null on update no action, foreign key("application_id") references applications("id") on delete set null on update no action, foreign key("mobility_call_id") references mobility_calls("id") on delete cascade on update no action, foreign key("erasmus_project_id") references erasmus_projects("id") on delete cascade on update no action, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "mobility_document_templates" ("id" integer primary key autoincrement not null, "profile" varchar not null, "phase" varchar not null, "document_type" varchar not null, "label" varchar not null, "required" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "mobility_documents" ("id" integer primary key autoincrement not null, "mobility_id" integer not null, "phase" varchar not null, "document_type" varchar not null, "label" varchar not null, "original_filename" varchar, "storage_path" varchar, "validation_status" varchar not null default 'pending_delivery', "coordinator_observations" text, "submitted_at" datetime, "validated_at" datetime, "validated_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("mobility_id") references "mobilities"("id") on delete cascade, foreign key("validated_by") references "users"("id") on delete set null);
DELETE FROM sqlite_sequence;
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "subject" on "activity_log" ("subject_type", "subject_id");
CREATE INDEX "causer" on "activity_log" ("causer_type", "causer_id");
CREATE INDEX "activity_log_log_name_index" on "activity_log" ("log_name");
CREATE UNIQUE INDEX "educational_centers_code_unique" on "educational_centers" ("code");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "erasmus_projects_project_code_unique" on "erasmus_projects" ("project_code");
CREATE UNIQUE INDEX "application_documents_application_id_document_type_unique" on "application_documents" ("application_id", "document_type");
CREATE UNIQUE INDEX "application_interviews_application_id_unique" on "application_interviews" ("application_id");
CREATE UNIQUE INDEX "mobility_bonds_mobility_id_unique" on "mobility_bonds" ("mobility_id");
CREATE UNIQUE INDEX "mobility_withdrawals_mobility_id_unique" on "mobility_withdrawals" ("mobility_id");
CREATE UNIQUE INDEX "domain_notifications_mobility_id_type_scheduled_for_unique" on "domain_notifications" ("mobility_id", "type", "scheduled_for");
CREATE UNIQUE INDEX "mobility_document_templates_profile_phase_document_type_unique" on "mobility_document_templates" ("profile", "phase", "document_type");
CREATE UNIQUE INDEX "mobility_documents_mobility_id_document_type_unique" on "mobility_documents" ("mobility_id", "document_type");
COMMIT;
PRAGMA foreign_keys=ON;
